-- 0012_seed_loja.sql — Fase 3 (doc 05 §3, §10 e §11): 10 categorias da Loja do Pai + 60 primeiros produtos.
-- Idempotente: `on conflict (slug) do update` (sem DELETE/TRUNCATE). Aplicar com mcp__Supabase__execute_sql
-- (ou apply_migration) no projeto <SUPABASE_PROJECT_REF>, depois da 0003_loja.sql.
--
-- Categorias: slugs da taxonomia do doc 04 §3 / doc 02 (os mesmos da 0003_loja.sql). O doc 05 §3 citava
-- `paternidade-pratica` (→ `bebe-e-crianca`) e `presentes-para-o-pai` (é rota/tag `/loja/presentes`, não
-- categoria; os 6 produtos de "presentes" entraram nas categorias reais). `saude-do-homem` fica sem produto
-- nesta seed (o doc 05 §10 não lista nenhum) — pendência registrada em progresso-fase-3.md.
--
-- Produtos: nome/marca/modelo reais do doc 05 §10, prós/contras e faixa de preço PLAUSÍVEL (max ≤ 3×min,
-- `price_range_checked_at` nulo: a fila de faixa de preço grava a pesquisa real). ASIN e fotos oficiais
-- NUNCA inventados: entram `null`, `affiliate_url` = busca na Amazon marcada PENDENTE e `active = false`.
-- Fluxo para ativar (admin /admin/produtos ou rotina): confirmar ASIN → `python3 scripts/rotina/amz.py <ASIN>`
-- (≥ 3 fotos _AC_SL1500_, HEAD 200, > 15 KB) → preencher asin/affiliate_url/images/image_url → active = true.
-- A reexecução desta seed preserva asin, fotos, faixa pesquisada, review e `active` já gravados no banco.
-- Os 5 primeiros (um por categoria-chave) trazem a review longa do doc 05 §11; os demais ficam `review = null`.

insert into public.product_categories (slug, name, icon, description, sort_order) values
  ('churrasco-e-cozinha', 'Churrasco e Cozinha', 'flame', 'Facas, tábuas, chapas, termômetros e o que faz diferença no fogo.', 1),
  ('ferramentas', 'Ferramentas', 'wrench', 'Furadeiras, parafusadeiras, kits e medição para consertar a casa.', 2),
  ('carro-e-moto', 'Carro e Moto', 'car', 'Manutenção, limpeza, segurança e acessórios do veículo.', 3),
  ('tecnologia', 'Tecnologia', 'smartphone', 'Eletrônicos úteis: leitura, som, energia, casa conectada e rede.', 4),
  ('esporte-e-outdoor', 'Esporte e Outdoor', 'tent', 'Acampamento, trilha, bola no quintal e equipamento para sair com os filhos.', 5),
  ('bebe-e-crianca', 'Bebê e Criança', 'baby', 'Canguru, cadeirinha, babá eletrônica: o que o pai usa com o filho no colo.', 6),
  ('casa-e-jardim', 'Casa e Jardim', 'home', 'Lavadora de pressão, grama, mangueira, escada e segurança da casa.', 7),
  ('saude-do-homem', 'Saúde do Homem', 'heart-pulse', 'Pressão, balança, sono, postura: o que ajuda o pai a estar inteiro.', 8),
  ('estilo-e-barba', 'Estilo e Barba', 'shirt', 'Barba, cabelo, perfume, relógio e carteira.', 9),
  ('livros-e-formacao', 'Livros e Formação', 'book-open', 'Leitura para ser homem, marido e pai melhor.', 10)
on conflict (slug) do update
  set name = excluded.name, icon = excluded.icon, description = excluded.description, sort_order = excluded.sort_order;

