on conflict (slug) do update set
  name = excluded.name,
  brand = excluded.brand,
  -- nunca sobrescrever o que o admin/rotina já confirmou no banco
  asin = coalesce(public.products.asin, excluded.asin),
  affiliate_url = case when public.products.asin is not null then public.products.affiliate_url else excluded.affiliate_url end,
  image_url = coalesce(public.products.image_url, excluded.image_url),
  images = case when jsonb_array_length(public.products.images) > 0 then public.products.images else excluded.images end,
  short_description = excluded.short_description,
  description = excluded.description,
  pros = excluded.pros,
  cons = excluded.cons,
  review = coalesce(public.products.review, excluded.review),
  category_id = excluded.category_id,
  subcategory = excluded.subcategory,
  price_min = case when public.products.price_range_checked_at is not null then public.products.price_min else excluded.price_min end,
  price_max = case when public.products.price_range_checked_at is not null then public.products.price_max else excluded.price_max end,
  featured = public.products.featured or excluded.featured,
  sort_order = excluded.sort_order,
  updated_at = now();

